-- Actual NumPy 2.5.3 choose; positive positions translated to Lua.
local np=require('luaray_core')
local cases,checks=0,0
local function eq(a,b,label)
 checks=checks+1
 if type(b)=='table' then
  assert(type(a)=='table' and #a==#b,label..': shape')
  for i=1,#b do eq(a[i],b[i],label..'['..i..']') end
 elseif type(b)=='number' and b~=b then assert(a~=a,label..': NaN')
 elseif type(b)=='userdata' then eq(a.real,b.real,label..'.real');eq(a.imag,b.imag,label..'.imag')
 else assert(a==b,label..': '..tostring(a)..' != '..tostring(b)) end
end

do
local function chunk()
-- 1: basic/int8/()/raise/[1, 2, -1]; source error=None
do
local indices=np.array(1,"int64")
local choices={np.array(10,"int8"),np.array(11,"int8")}
local ok,result=pcall(function() return np.choose(indices,choices,{mode="raise"}) end)
assert(ok==true,"basic/int8/()/raise/[1, 2, -1]: acceptance"..": "..tostring(result))
eq(result,10,"basic/int8/()/raise/[1, 2, -1]: scalar")
eq(indices:tolist(),1,"basic/int8/()/raise/[1, 2, -1]: indices")
eq(indices.shape,{},"basic/int8/()/raise/[1, 2, -1]: indices: shape")
eq(indices.strides,{},"basic/int8/()/raise/[1, 2, -1]: indices: strides")
eq(indices.dtype,"int64","basic/int8/()/raise/[1, 2, -1]: indices: dtype")
cases=cases+1
end
