local choices={np.array({"1","2","3"},"|S4"),np.array(8,"int32")}
local out=np.array({"bad","bad","bad"},"<U4")
local ok,result=pcall(function() return np.choose(indices,choices,{mode="clip",out=out}) end)
assert(ok==true,"promotion-out/S4/int32/clip: acceptance"..": "..tostring(result))
eq(result:tolist(),{"1","8","3"},"promotion-out/S4/int32/clip: result")
eq(result.shape,{3},"promotion-out/S4/int32/clip: result: shape")
eq(result.strides,{16},"promotion-out/S4/int32/clip: result: strides")
eq(result.dtype,"<U4","promotion-out/S4/int32/clip: result: dtype")
assert(result==out,"promotion-out/S4/int32/clip: output identity")
eq(indices:tolist(),{1,2,1},"promotion-out/S4/int32/clip: indices")
eq(indices.shape,{3},"promotion-out/S4/int32/clip: indices: shape")
eq(indices.strides,{8},"promotion-out/S4/int32/clip: indices: strides")
eq(indices.dtype,"int64","promotion-out/S4/int32/clip: indices: dtype")
eq(out:tolist(),{"1","8","3"},"promotion-out/S4/int32/clip: output state")
eq(out.shape,{3},"promotion-out/S4/int32/clip: output state: shape")
eq(out.strides,{16},"promotion-out/S4/int32/clip: output state: strides")
eq(out.dtype,"<U4","promotion-out/S4/int32/clip: output state: dtype")
cases=cases+1
end
