local choices={np.array({1,1},"datetime64[h]")}
local out=np.array({"xxxx","xxxx"},"|S38")
local ok,result=pcall(function() return np.choose(indices,choices,{mode="raise",out=out}) end)
assert(ok==true,"iso-width/h/1/S38: acceptance"..": "..tostring(result))
eq(result:tolist(),{"1970-01-01T01","1970-01-01T01"},"iso-width/h/1/S38: result")
eq(result.shape,{2},"iso-width/h/1/S38: result: shape")
eq(result.strides,{38},"iso-width/h/1/S38: result: strides")
eq(result.dtype,"|S38","iso-width/h/1/S38: result: dtype")
assert(result==out,"iso-width/h/1/S38: output identity")
eq(indices:tolist(),{1,1},"iso-width/h/1/S38: indices")
eq(indices.shape,{2},"iso-width/h/1/S38: indices: shape")
eq(indices.strides,{8},"iso-width/h/1/S38: indices: strides")
eq(indices.dtype,"int64","iso-width/h/1/S38: indices: dtype")
eq(out:tolist(),{"1970-01-01T01","1970-01-01T01"},"iso-width/h/1/S38: output state")
eq(out.shape,{2},"iso-width/h/1/S38: output state: shape")
eq(out.strides,{38},"iso-width/h/1/S38: output state: strides")
eq(out.dtype,"|S38","iso-width/h/1/S38: output state: dtype")
cases=cases+1
end
